/**
 * The help content shipped with the application: Markdown files `src/help/<audience>/NN-name.md`
 * and the screenshots `src/help/img/*` (generated by `e2e/shots/help-shots.ts`). Imported by the
 * lazy `/aide` page only: nothing of it is part of the initial bundle.
 */
import { buildCatalog, type HelpSection } from './catalog';

const files = import.meta.glob('../../help/*/*.md', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>;

const images = import.meta.glob('../../help/img/*.{webp,png}', {
  query: '?url',
  import: 'default',
  eager: true,
}) as Record<string, string>;

/** Help sections built from the bundled Markdown files. */
export const helpSections: readonly HelpSection[] = buildCatalog(files);

const stem = (name: string): string => name.replace(/\.[a-z0-9]+$/i, '');

/** Screenshots by file stem: `editeur.webp` in the Markdown finds `editeur.webp` or `editeur.png`. */
const imageByStem = new Map(
  Object.entries(images).map(([path, url]) => [stem(path.slice(path.lastIndexOf('/') + 1)), url]),
);

/** URL of a screenshot by file name, or null when it does not exist. */
export function helpImageUrl(name: string): string | null {
  return imageByStem.get(stem(name)) ?? null;
}

/** File stems of the available screenshots. */
export function helpImageNames(): string[] {
  return [...imageByStem.keys()];
}
